SELECT EXTRACT(YEAR FROM o_entry_d) AS l_year, SUM(CASE WHEN n2.n_name = 'GERMANY' THEN ol_amount ELSE 0 END) / SUM(ol_amount) AS mkt_share FROM tpcch.item, tpcch.supplier, tpcch.stock, tpcch.orderline, order_view, tpcch.customer, tpcch.nation AS n1, tpcch.nation AS n2, tpcch.region WHERE i_id = s_i_id AND ol_i_id = s_i_id AND ol_supply_w_id = s_w_id AND s_su_suppkey = su_suppkey AND ol_w_id = o_w_id AND ol_d_id = o_d_id AND ol_o_id = o_id AND c_id = o_c_id AND c_w_id = o_w_id AND c_d_id = o_d_id AND n1.n_nationkey = c_n_nationkey AND n1.n_regionkey = r_regionkey AND ol_i_id < 1000 AND r_name = 'EUROPE' AND su_nationkey = n2.n_nationkey AND o_entry_d BETWEEN '2007-01-02 00:00:00.000000' AND '2012-01-02 00:00:00.000000' AND i_data LIKE '%b' AND i_id = ol_i_id GROUP BY EXTRACT(YEAR FROM o_entry_d) ORDER BY l_year;
